#pragma once
#include "ksInternalMidiServiceTask.h"
#include "ksSerialForegroundService.h"
#include "ksNativeMidiQueueService.h"
#include "ksNativeMidiInitializationService.h"
#include "ksNativeMidiDomainBindings.h"
#include <type_traits>
#include <functional>
namespace ks {
class NativeMidiPumpService final {
public:
 enum class Component{Policy,Serial,Queue,Decode,QueuedDecode,ParserReset};enum class Notice{Policy,Serial,Queue,Decode,QueuedDecode,ParserReset,SystemReset,SysExReset};
 struct Input{uint8_t activation=0;};struct Effect{bool read=false,write=false;};
 struct Summary{Input input{};uint64_t receiveBytes=0,queueBytes=0,receivePops=0,queuePops=0,receiveResets=0,queueResets=0;bool activationKnown=false;uint8_t activation=0;uint32_t expressionSourceMask=0,expressionSource=0;};
 struct IgnoreObserver{template<class...T>void operator()(T&&...)const noexcept{}};
 NativeMidiPumpService():NativeMidiPumpService(Input{}){}explicit NativeMidiPumpService(Input i):policy_(InternalMidiServiceTask::Kind::Pump){summary_.input=i;summary_.activation=i.activation;}
 bool complete()const{return policy_.complete();}Component component()const{return component_;}const Effect&effect()const{return effect_;}const Summary&summary()const{return summary_;}const InternalMidiServiceTask&policyTask()const{return policy_;}const SerialForegroundService*serialOutcome()const{return serial_?&*serial_:nullptr;}const NativeMidiQueueService*queueOutcome()const{return queue_?&*queue_:nullptr;}const NativeMidiDecodeService*decodeOutcome()const{return decode_?&*decode_:nullptr;}const NativeQueuedMidiDecodeService*queuedDecodeOutcome()const{return queued_?&*queued_:nullptr;}const NativeMidiInitializationService*parserOutcome()const{return parser_?&*parser_:nullptr;}
 unsigned priority()const{switch(component_){case Component::Serial:return serial_->critical()?7:0;case Component::Decode:return decode_->priority();case Component::QueuedDecode:return queued_->priority();case Component::ParserReset:return parser_->priority();default:return 0;}}bool critical()const{return priority()==7;}
 template<class T>const T*task()const{if(complete())return nullptr;if constexpr(std::is_same_v<T,InternalMidiServiceTask>)return component_==Component::Policy?&policy_:nullptr;else if constexpr(std::is_same_v<T,SerialForegroundService>)return component_==Component::Serial?&*serial_:nullptr;else{switch(component_){case Component::Queue:return queue_->template task<T>();case Component::Decode:return decode_->template task<T>();case Component::QueuedDecode:return queued_->template task<T>();case Component::ParserReset:return parser_->template task<T>();default:return nullptr;}}}
 unsigned nextClocks(int previous=-1)const{switch(component_){case Component::Policy:return policy_.nextClocks();case Component::Serial:return serial_->nextClocks();case Component::Queue:return queue_->nextClocks(previous);case Component::Decode:return decode_->nextClocks(previous);case Component::QueuedDecode:return queued_->nextClocks(previous);case Component::ParserReset:return parser_->nextClocks(previous);}return 0;}
 template<class R,class W,class Resolver>unsigned advanceBefore(unsigned budget,R&&read,W&&write,Resolver&&resolve,int previous=-1){return advanceBefore(budget,read,write,resolve,IgnoreObserver{},previous);}
 // The observer is an external migration sidecar only: void-only, after an
 // admitted phase, no answers, no access to mutable native state. A no-op
 // observer executes the identical pure graph and resource callbacks.
 template<class R,class W,class Resolver,class Observer>unsigned advanceBefore(unsigned budget,R&&read,W&&write,Resolver&&resolve,Observer&&observe,int previous){static_assert(std::is_void_v<std::invoke_result_t<Observer&,Notice,InternalMidiServiceTask::Stage,const NativeMidiPumpService&>>,"MIDI Pump observer must return void");const auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;effect_={};const auto stage=policy_.stage();Notice notice=Notice::Policy;
 if(component_==Component::Serial){notice=Notice::Serial;using S=SerialQueueTask::Stage;effect_.write=serial_->atQueue(S::RetainCritical)||serial_->atQueue(S::RetainWord)||serial_->atQueue(S::RetainFirst)||serial_->atQueue(S::RetainSecond);effect_.read=serial_->atQueue(S::RestoreWord)||serial_->atQueue(S::RestoreCritical)||serial_->atQueue(S::RestoreSecond)||serial_->atQueue(S::RestoreFirst)||serial_->atQueue(S::Finish);serial_->advanceBefore(cost,read,write);if(serial_->complete()){received_=serial_->result();policy_.resumeChild(received_);component_=Component::Policy;}}
 else if(component_==Component::Queue){notice=Notice::Queue;queue_->advanceBefore(cost,read,write,previous);effect_={queue_->effect().read,queue_->effect().write};if(queue_->complete()){queuedByte_=queue_->result();policy_.resumeChild(queuedByte_);component_=Component::Policy;}}
 else if(component_==Component::Decode){notice=Notice::Decode;decode_->advanceBefore(cost,read,write,resolve,previous);effect_={decode_->effect().read,decode_->effect().write};if(decode_->complete()){summary_.activation=decode_->result().activation;merge(midiDecodeExpressionTransfer(*decode_));policy_.resumeChild(0);component_=Component::Policy;}}
 else if(component_==Component::QueuedDecode){notice=Notice::QueuedDecode;queued_->advanceBefore(cost,read,write,resolve,previous);effect_={queued_->effect().read,queued_->effect().write};if(queued_->complete()){summary_.activation=queued_->result().activation;merge(queuedMidiDecodeExpressionTransfer(*queued_));policy_.resumeChild(0);component_=Component::Policy;}}
 else if(component_==Component::ParserReset){notice=Notice::ParserReset;parser_->advanceBefore(cost,read,write,previous);effect_={parser_->effect().read,parser_->effect().write};if(parser_->complete()){policy_.resumeChild(0);component_=Component::Policy;}}
 else{using S=InternalMidiServiceTask::Stage;policy_.advanceBefore(cost,[](auto)->uint32_t{throw std::logic_error("Unexpected Pump policy read");},[](auto,auto){throw std::logic_error("Unexpected Pump policy write");});if(stage==S::ReturnPump){effect_.read=true;summary_.activationKnown=true;}else if(policy_.awaitingChild()){effect_.write=true;switch(stage){case S::PopReceive:serial_.emplace(SerialForegroundService::Kind::PopRx);++summary_.receivePops;component_=Component::Serial;break;case S::ParseReceive:decode_.emplace(NativeMidiDecodeService::Input{uint8_t(received_),summary_.activation,0});++summary_.receiveBytes;component_=Component::Decode;break;case S::ClearReceive:serial_.emplace(SerialForegroundService::Kind::ResetRx);++summary_.receiveResets;component_=Component::Serial;break;case S::PopQueue:queue_.emplace(NativeMidiQueueService::Kind::Pop);++summary_.queuePops;component_=Component::Queue;break;case S::ParseQueue:queued_.emplace(NativeQueuedMidiDecodeService::Input{uint8_t(queuedByte_),summary_.activation});++summary_.queueBytes;component_=Component::QueuedDecode;break;case S::ClearQueue:queue_.emplace(NativeMidiQueueService::Kind::Reset);++summary_.queueResets;component_=Component::Queue;break;default:throw std::logic_error("Unsupported Pump child");}}}
 observe(notice,stage,static_cast<const NativeMidiPumpService&>(*this));return cost;
 }
private:
 void merge(ExpressionSourceTransfer x){summary_.expressionSource=(summary_.expressionSource&~x.mask)|(x.value&x.mask);summary_.expressionSourceMask|=x.mask;}
 InternalMidiServiceTask policy_;Component component_=Component::Policy;Effect effect_{};Summary summary_{};uint16_t received_=0,queuedByte_=0;std::optional<SerialForegroundService>serial_;std::optional<NativeMidiQueueService>queue_;std::optional<NativeMidiDecodeService>decode_;std::optional<NativeQueuedMidiDecodeService>queued_;std::optional<NativeMidiInitializationService>parser_;
};
inline uint16_t midiPumpPresentationAfter(const NativeMidiPumpService&s,uint16_t){if(!s.complete())throw std::logic_error("Incomplete Pump presentation domain outcome");return 0;}
}
